fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    // Handle the case where n is 0 or len is 1 to avoid unnecessary calculations
    if len == 1 || n % len == 0 {
        return list.clone();
    }
    
    let s = len - (n % len);
    
    // Create a new vector with the same capacity as the input
    let mut result = Vec::with_capacity(len);
    
    // Add the suffix: from index s to len-1
    result.extend_from_slice(&list[s..]);
    
    // Add the prefix: from index 0 to s-1
    result.extend_from_slice(&list[..s]);
    
    result
}